import matplotlib.pyplot as plt
import numpy as np


def plotting(prevalence, ppv_plots_lab, f1_score_plots_lab, accuracy_plots_lab, sens_plots_lab, spec_plots_lab,
             ppv_plots_real, f1_score_plots_real, accuracy_plots_real, sens_plots_real, spec_plots_real):
    #plotting results for main simulation
    prev_004 = np.argwhere(np.abs(prevalence - 0.04) < 0.002)[0]
    prev_054 = np.argwhere(np.abs(prevalence - 0.54) < 0.005)[0]
    fig, ax = plt.subplots(1,5)
    fig.set_figheight(5)
    fig.set_figwidth(25)
    #plot lab results
    ax[0].set_ylabel('PPV')
    ax[1].set_ylabel('F1 score')
    ax[2].set_ylabel('Accuracy')
    ax[3].set_ylabel('Sensitivity')
    ax[4].set_ylabel('Specificity')
    ax[0].set_xlabel('Prevalence')
    ax[1].set_xlabel('Prevalence')
    ax[2].set_xlabel('Prevalence')
    ax[3].set_xlabel('Prevalence')
    ax[4].set_xlabel('Prevalence')
    ax[0].set_ylim(0,1)
    ax[1].set_ylim(0,1)
    ax[2].set_ylim(0,1)
    ax[3].set_ylim(0,1)
    ax[4].set_ylim(0,1)
    ax[0].vlines([0.04, 0.54], ymin=0, ymax=1, linestyle='--', color='gray', linewidth=1)
    ax[1].vlines([0.04, 0.54], ymin=0, ymax=1, linestyle='--', color='gray', linewidth=1)
    ax[2].vlines([0.04, 0.54], ymin=0, ymax=1, linestyle='--', color='gray', linewidth=1)
    ax[3].vlines([0.04, 0.54], ymin=0, ymax=1, linestyle='--', color='gray', linewidth=1)
    ax[4].vlines([0.04, 0.54], ymin=0, ymax=1, linestyle='--', color='gray', linewidth=1)
    ax[0].plot(prevalence, np.mean(ppv_plots_lab, axis=0), label='Lab')
    ax[0].fill_between(prevalence, np.mean(ppv_plots_lab, axis=0)-np.std(ppv_plots_lab, axis=0), np.mean(ppv_plots_lab, axis=0)+np.std(ppv_plots_lab, axis=0), color='blue', alpha=0.2)
    ax[0].fill_between(prevalence, np.mean(ppv_plots_lab, axis=0)-2*np.std(ppv_plots_lab, axis=0), np.mean(ppv_plots_lab, axis=0)+2*np.std(ppv_plots_lab, axis=0), color='blue', alpha=0.1)
    ax[0].plot(prevalence[prev_054], np.array(np.mean(ppv_plots_lab, axis=0))[prev_054], 'k.', label= '_nolegend_')
    ax[0].text(prevalence[prev_054], np.array(np.mean(ppv_plots_lab, axis=0))[prev_054], str(round(np.array(np.mean(ppv_plots_lab, axis=0))[prev_054][0], 2)))
    ax[0].plot(prevalence[prev_004], np.array(np.mean(ppv_plots_lab, axis=0))[prev_004], 'k.', label= '_nolegend_')
    ax[0].text(prevalence[prev_004], np.array(np.mean(ppv_plots_lab, axis=0))[prev_004], str(round(np.array(np.mean(ppv_plots_lab, axis=0))[prev_004][0], 2)))
