    ax[1].fill_between(prevalence, np.mean(f1_score_plots_lab, axis=0)-2*np.std(f1_score_plots_lab, axis=0), np.mean(f1_score_plots_lab, axis=0)+2*np.std(f1_score_plots_lab, axis=0), color='blue', alpha=0.1)
    ax[1].plot(prevalence[prev_054], np.array(np.mean(f1_score_plots_lab, axis=0))[prev_054], 'k.', label= '_nolegend_')
