    ax[3].text(prevalence[prev_054], np.array(np.mean(sens_plots_lab, axis=0))[prev_054], str(round(np.array(np.mean(sens_plots_lab, axis=0))[prev_054][0], 2)))
    ax[3].plot(prevalence[prev_004], np.array(np.mean(sens_plots_lab, axis=0))[prev_004], 'k.', label= '_nolegend_')
