    ax[4].fill_between(prevalence, np.mean(spec_plots_lab, axis=0)-2*np.std(spec_plots_lab, axis=0), np.mean(spec_plots_lab, axis=0)+2*np.std(spec_plots_lab, axis=0), color='blue', alpha=0.1)
    ax[4].plot(prevalence[prev_054], np.array(np.mean(spec_plots_lab, axis=0))[prev_054], 'k.', label= '_nolegend_')
    ax[4].text(prevalence[prev_054], np.array(np.mean(spec_plots_lab, axis=0))[prev_054], str(round(np.array(np.mean(spec_plots_lab, axis=0))[prev_054][0], 2)))
    ax[4].plot(prevalence[prev_004], np.array(np.mean(spec_plots_lab, axis=0))[prev_004], 'k.', label= '_nolegend_')
    ax[4].text(prevalence[prev_004], np.array(np.mean(spec_plots_lab, axis=0))[prev_004], str(round(np.array(np.mean(spec_plots_lab, axis=0))[prev_004][0], 2)))
    #plot real results
    ax[0].plot(prevalence, np.mean(ppv_plots_real, axis=0), label='Free-living')
    ax[0].fill_between(prevalence, np.mean(ppv_plots_real, axis=0)-np.std(ppv_plots_real, axis=0), np.mean(ppv_plots_real, axis=0)+np.std(ppv_plots_real, axis=0), color='orange', alpha=0.2)
    ax[0].fill_between(prevalence, np.mean(ppv_plots_real, axis=0)-2*np.std(ppv_plots_real, axis=0), np.mean(ppv_plots_real, axis=0)+2*np.std(ppv_plots_real, axis=0), color='orange', alpha=0.1)
    ax[0].plot(prevalence[prev_054], np.array(np.mean(ppv_plots_real, axis=0))[prev_054], 'k.', label= '_nolegend_')
    ax[0].text(prevalence[prev_054], np.array(np.mean(ppv_plots_real, axis=0))[prev_054], str(round(np.array(np.mean(ppv_plots_real, axis=0))[prev_054][0], 2)))
    ax[0].plot(prevalence[prev_004], np.array(np.mean(ppv_plots_real, axis=0))[prev_004], 'k.', label= '_nolegend_')
    ax[0].text(prevalence[prev_004], np.array(np.mean(ppv_plots_real, axis=0))[prev_004], str(round(np.array(np.mean(ppv_plots_real, axis=0))[prev_004][0], 2)))
    ax[1].plot(prevalence, np.mean(f1_score_plots_real, axis=0), label='Free-living')
    ax[1].fill_between(prevalence, np.mean(f1_score_plots_real, axis=0)-np.std(f1_score_plots_real, axis=0), np.mean(f1_score_plots_real, axis=0)+np.std(f1_score_plots_real, axis=0), color='orange', alpha=0.2)
    ax[1].fill_between(prevalence, np.mean(f1_score_plots_real, axis=0)-2*np.std(f1_score_plots_real, axis=0), np.mean(f1_score_plots_real, axis=0)+2*np.std(f1_score_plots_real, axis=0), color='orange', alpha=0.1)
    ax[1].plot(prevalence[prev_054], np.array(np.mean(f1_score_plots_real, axis=0))[prev_054], 'k.', label= '_nolegend_')
    ax[1].text(prevalence[prev_054], np.array(np.mean(f1_score_plots_real, axis=0))[prev_054], str(round(np.array(np.mean(f1_score_plots_real, axis=0))[prev_054][0], 2)))
    ax[1].plot(prevalence[prev_004], np.array(np.mean(f1_score_plots_real, axis=0))[prev_004], 'k.', label= '_nolegend_')
    ax[1].text(prevalence[prev_004], np.array(np.mean(f1_score_plots_real, axis=0))[prev_004], str(round(np.array(np.mean(f1_score_plots_real, axis=0))[prev_004][0], 2)))
    ax[2].plot(prevalence, np.mean(accuracy_plots_real, axis=0), label='Free-living')
    ax[2].fill_between(prevalence, np.mean(accuracy_plots_real, axis=0)-np.std(accuracy_plots_real, axis=0), np.mean(accuracy_plots_real, axis=0)+np.std(accuracy_plots_real, axis=0), color='orange', alpha=0.2)
    ax[2].fill_between(prevalence, np.mean(accuracy_plots_real, axis=0)-2*np.std(accuracy_plots_real, axis=0), np.mean(accuracy_plots_real, axis=0)+2*np.std(accuracy_plots_real, axis=0), color='orange', alpha=0.1)
    ax[2].plot(prevalence[prev_054], np.array(np.mean(accuracy_plots_real, axis=0))[prev_054], 'k.', label= '_nolegend_')
    ax[2].text(prevalence[prev_054], np.array(np.mean(accuracy_plots_real, axis=0))[prev_054], str(round(np.array(np.mean(accuracy_plots_real, axis=0))[prev_054][0], 2)))
    ax[2].plot(prevalence[prev_004], np.array(np.mean(accuracy_plots_real, axis=0))[prev_004], 'k.', label= '_nolegend_')
    ax[2].text(prevalence[prev_004], np.array(np.mean(accuracy_plots_real, axis=0))[prev_004], str(round(np.array(np.mean(accuracy_plots_real, axis=0))[prev_004][0], 2)))
