    ax[3].fill_between(prevalence, np.mean(sens_plots_real, axis=0)-np.std(sens_plots_real, axis=0), np.mean(sens_plots_real, axis=0)+np.std(sens_plots_real, axis=0), color='orange', alpha=0.2)
