def plotting_sensitivity_analysis(prevalence, ppv_plots_disease_mimics, ppv_plots_noise, ppv_plots_fpr):
    #plotting results for sensitivity analysis
    prev_004 = np.argwhere(np.abs(prevalence - 0.04) < 0.002)[0]
    prev_054 = np.argwhere(np.abs(prevalence - 0.54) < 0.005)[0]
    fig, ax = plt.subplots(1,3)
    fig.set_figheight(5)
    fig.set_figwidth(16)
    #plotting disease mimic results
    ax[0].set_ylim(0,1)
    ax[0].vlines([0.04, 0.54], ymin=0, ymax=1, linestyle='--', color='gray', linewidth=1)
    ax[0].plot(prevalence, np.mean(ppv_plots_disease_mimics, axis=0), label='Lab')
    ax[0].fill_between(prevalence, np.mean(ppv_plots_disease_mimics, axis=0)-np.std(ppv_plots_disease_mimics, axis=0), np.mean(ppv_plots_disease_mimics, axis=0)+np.std(ppv_plots_disease_mimics, axis=0), color='blue', alpha=0.2)
    ax[0].fill_between(prevalence, np.mean(ppv_plots_disease_mimics, axis=0)-2*np.std(ppv_plots_disease_mimics, axis=0), np.mean(ppv_plots_disease_mimics, axis=0)+2*np.std(ppv_plots_disease_mimics, axis=0), color='blue', alpha=0.1)
    ax[0].plot(prevalence[prev_004], np.array(np.mean(ppv_plots_disease_mimics, axis=0))[prev_004], 'k.', label= '_nolegend_')
    ax[0].text(prevalence[prev_004], np.array(np.mean(ppv_plots_disease_mimics, axis=0))[prev_004], str(round(np.array(np.mean(ppv_plots_disease_mimics, axis=0))[prev_004][0], 2)))
    ax[0].plot(prevalence[prev_054], np.array(np.mean(ppv_plots_disease_mimics, axis=0))[prev_054], 'k.', label= '_nolegend_')
    ax[0].text(prevalence[prev_054], np.array(np.mean(ppv_plots_disease_mimics, axis=0))[prev_054], str(round(np.array(np.mean(ppv_plots_disease_mimics, axis=0))[prev_054][0], 2)))
    ax[0].set_xlabel('Prevalence')
    ax[0].set_ylabel('PPV')
    ax[0].set_title('Disease mimics')
    #plotting noise results
    ax[1].set_ylim(0,1)
    ax[1].vlines([0.04, 0.54], ymin=0, ymax=1, linestyle='--', color='gray', linewidth=1)
    ax[1].plot(prevalence, np.mean(ppv_plots_noise, axis=0), label='Lab')
    ax[1].fill_between(prevalence, np.mean(ppv_plots_noise, axis=0)-np.std(ppv_plots_noise, axis=0), np.mean(ppv_plots_noise, axis=0)+np.std(ppv_plots_noise, axis=0), color='blue', alpha=0.2)
    ax[1].fill_between(prevalence, np.mean(ppv_plots_noise, axis=0)-2*np.std(ppv_plots_noise, axis=0), np.mean(ppv_plots_noise, axis=0)+2*np.std(ppv_plots_noise, axis=0), color='blue', alpha=0.1)
    ax[1].plot(prevalence[prev_004], np.array(np.mean(ppv_plots_noise, axis=0))[prev_004], 'k.', label= '_nolegend_')
    ax[1].text(prevalence[prev_004], np.array(np.mean(ppv_plots_noise, axis=0))[prev_004], str(round(np.array(np.mean(ppv_plots_noise, axis=0))[prev_004][0], 2)))
    ax[1].plot(prevalence[prev_054], np.array(np.mean(ppv_plots_noise, axis=0))[prev_054], 'k.', label= '_nolegend_')
    ax[1].text(prevalence[prev_054], np.array(np.mean(ppv_plots_noise, axis=0))[prev_054], str(round(np.array(np.mean(ppv_plots_noise, axis=0))[prev_054][0], 2)))
    ax[1].set_xlabel('Prevalence')
    ax[1].set_ylabel('PPV')
    ax[1].set_title('Noise')
    #plotting fpr results
    ax[2].set_ylim(0,1)
    ax[2].vlines([0.04, 0.54], ymin=0, ymax=1, linestyle='--', color='gray', linewidth=1)
    ax[2].plot(prevalence, np.mean(ppv_plots_fpr, axis=0), label='Lab')
    ax[2].fill_between(prevalence, np.mean(ppv_plots_fpr, axis=0)-np.std(ppv_plots_fpr, axis=0), np.mean(ppv_plots_fpr, axis=0)+np.std(ppv_plots_fpr, axis=0), color='blue', alpha=0.2)
    ax[2].fill_between(prevalence, np.mean(ppv_plots_fpr, axis=0)-2*np.std(ppv_plots_fpr, axis=0), np.mean(ppv_plots_fpr, axis=0)+2*np.std(ppv_plots_fpr, axis=0), color='blue', alpha=0.1)
    ax[2].plot(prevalence[prev_004], np.array(np.mean(ppv_plots_fpr, axis=0))[prev_004], 'k.', label= '_nolegend_')
    ax[2].text(prevalence[prev_004], np.array(np.mean(ppv_plots_fpr, axis=0))[prev_004], str(round(np.array(np.mean(ppv_plots_fpr, axis=0))[prev_004][0], 2)))
    ax[2].plot(prevalence[prev_054], np.array(np.mean(ppv_plots_fpr, axis=0))[prev_054], 'k.', label= '_nolegend_')
    ax[2].text(prevalence[prev_054], np.array(np.mean(ppv_plots_fpr, axis=0))[prev_054], str(round(np.array(np.mean(ppv_plots_fpr, axis=0))[prev_054][0], 2)))
    ax[2].set_xlabel('Prevalence')
    ax[2].set_ylabel('PPV')
    ax[2].set_title('FPR in controlled conditions')

    plt.show()